import { Badge } from '@refy-design/web';
import { BillingCard } from '@refy-design/web';
import { Button } from '@refy-design/web';
import { Drawer } from '@refy-design/web';
import { Input } from '@refy-design/web';
import { Table } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function BillingCardExample() {
  const [panel, setPanel] = useState(''),
    [digits, setDigits] = useState('4242'),
    [draft, setDraft] = useState('4242');
  return (
    <>
      <BillingCard
        methodLabel="Demo method"
        lastDigits={digits}
        methodMeta="Do not use real data. Nothing is charged."
        status={<Badge tone="success">Active</Badge>}
        nextChargeAmount="R$ 199"
        nextChargeDate="on Oct 24, 2026"
        actions={
          <>
            <Button onClick={() => setPanel('invoices')}>View invoices</Button>
            <Button
              onClick={() => {
                setDraft(digits);
                setPanel('method');
              }}
            >
              Change card
            </Button>
          </>
        }
      />
      <Drawer
        open={Boolean(panel)}
        onOpenChange={(open) => {
          if (!open) setPanel('');
        }}
        title={panel === 'invoices' ? 'Sample invoices' : 'Edit demo method'}
      >
        {panel === 'invoices' ? (
          <Table
            caption="Sample invoices"
            rows={[
              { id: 'out', month: 'October', value: 'R$ 199', status: 'Paid' },
              { id: 'set', month: 'September', value: 'R$ 199', status: 'Paid' },
            ]}
            rowKey={(r) => r.id}
            columns={[
              { key: 'month', header: 'Month', cell: (r) => r.month },
              { key: 'value', header: 'Amount', cell: (r) => r.value },
              { key: 'status', header: 'State', cell: (r) => r.status },
            ]}
          />
        ) : (
          <form
            style={stack}
            onSubmit={(e) => {
              e.preventDefault();
              setDigits(draft);
              setPanel('');
            }}
          >
            <Input
              label="Four made-up digits"
              inputMode="numeric"
              pattern="[0-9]{4}"
              maxLength={4}
              required
              value={draft}
              onChange={(e) => setDraft(e.target.value.replace(/\D/g, ''))}
              hint="Just a made-up four-digit identifier."
            />
            <Button type="submit" variant="primary">
              Save method
            </Button>
          </form>
        )}
      </Drawer>
    </>
  );
}
export function Example() {
  return <BillingCardExample />;
}
